CREATE TABLE IF NOT EXISTS "customers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Login and contact address. Unique because return abuse is tracked per identity, and a duplicate identity defeats the whole risk table.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Name for correspondence and for matching against the shipping label on an inbound parcel.
	"full_name" VARCHAR(160) NOT NULL,
	-- Account creation. Tenure is one of the cheapest signals available when deciding whether to trust a claim.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Hard block after repeated confirmed abuse. Separate from account suspension, because a customer may still buy while being denied free returns.
	"is_blocked_from_returns" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "customers" IS 'The returning party. Deliberately thin — the interesting behaviour lives in customer_return_risk, which is recomputed rather than edited by hand.';
COMMENT ON COLUMN "customers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "customers"."email" IS 'Login and contact address. Unique because return abuse is tracked per identity, and a duplicate identity defeats the whole risk table.';
COMMENT ON COLUMN "customers"."full_name" IS 'Name for correspondence and for matching against the shipping label on an inbound parcel.';
COMMENT ON COLUMN "customers"."created_at" IS 'Account creation. Tenure is one of the cheapest signals available when deciding whether to trust a claim.';
COMMENT ON COLUMN "customers"."is_blocked_from_returns" IS 'Hard block after repeated confirmed abuse. Separate from account suspension, because a customer may still buy while being denied free returns.';

CREATE TABLE IF NOT EXISTS "sales_orders" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Buyer. A return is always anchored to the order, never to a bare product.
	"customer_id" BIGINT NOT NULL,
	-- Reference the customer quotes when starting a return.
	"order_number" VARCHAR(32) NOT NULL UNIQUE,
	-- When the order was placed.
	"placed_at" TIMESTAMPTZ NOT NULL,
	-- Delivery confirmation from the carrier. This, not the order date, is what the eligibility window counts from, because a parcel that took three weeks should not eat the window.
	"delivered_at" TIMESTAMPTZ,
	-- ISO 4217 currency the order was paid in. A refund must be in the same currency at the same rate, or the customer is refunded a different amount than they paid.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- web | app | marketplace | retail. Marketplace and retail orders have their own return rules imposed from outside.
	"channel" VARCHAR(24) NOT NULL DEFAULT 'web',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "sales_orders" IS 'The forward order, kept only as far as returns need it. It is the eligibility anchor: what was bought, when it arrived, what was paid and in which currency.';
COMMENT ON COLUMN "sales_orders"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "sales_orders"."customer_id" IS 'Buyer. A return is always anchored to the order, never to a bare product.';
COMMENT ON COLUMN "sales_orders"."order_number" IS 'Reference the customer quotes when starting a return.';
COMMENT ON COLUMN "sales_orders"."placed_at" IS 'When the order was placed.';
COMMENT ON COLUMN "sales_orders"."delivered_at" IS 'Delivery confirmation from the carrier. This, not the order date, is what the eligibility window counts from, because a parcel that took three weeks should not eat the window.';
COMMENT ON COLUMN "sales_orders"."currency_code" IS 'ISO 4217 currency the order was paid in. A refund must be in the same currency at the same rate, or the customer is refunded a different amount than they paid.';
COMMENT ON COLUMN "sales_orders"."channel" IS 'web | app | marketplace | retail. Marketplace and retail orders have their own return rules imposed from outside.';

CREATE INDEX "idx_orders_customer_placed"
ON "sales_orders" ("customer_id", "placed_at");

CREATE TABLE IF NOT EXISTS "sales_order_lines" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent order.
	"sales_order_id" BIGINT NOT NULL,
	-- Item purchased.
	"sku" VARCHAR(64) NOT NULL,
	-- Description snapshotted at purchase, so a renamed product does not make an old return unreadable.
	"product_name" VARCHAR(200) NOT NULL,
	-- Units bought on this line. The ceiling on everything that can ever be returned against it.
	"quantity" INTEGER NOT NULL,
	-- Price per unit actually charged, in minor units, after discounts. The refundable amount derives from this and nothing else.
	"unit_price_minor" BIGINT NOT NULL,
	-- Tax charged on this line in minor units, refunded proportionally to the units returned.
	"tax_minor" BIGINT NOT NULL DEFAULT 0,
	-- Discount applied to this line. Refunding the list price of a discounted item is the most common way money leaks out of a returns process.
	"discount_minor" BIGINT NOT NULL DEFAULT 0,
	-- True for clearance and personalised goods that cannot be returned. Stored per line because the policy at purchase time is what binds, not the policy today.
	"is_final_sale" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "sales_order_lines" IS 'What was bought, at what price. Returns are authorised against a line rather than a SKU so that the refund amount is a fact from the original transaction and not a lookup of the current price.';
COMMENT ON COLUMN "sales_order_lines"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "sales_order_lines"."sales_order_id" IS 'Parent order.';
COMMENT ON COLUMN "sales_order_lines"."sku" IS 'Item purchased.';
COMMENT ON COLUMN "sales_order_lines"."product_name" IS 'Description snapshotted at purchase, so a renamed product does not make an old return unreadable.';
COMMENT ON COLUMN "sales_order_lines"."quantity" IS 'Units bought on this line. The ceiling on everything that can ever be returned against it.';
COMMENT ON COLUMN "sales_order_lines"."unit_price_minor" IS 'Price per unit actually charged, in minor units, after discounts. The refundable amount derives from this and nothing else.';
COMMENT ON COLUMN "sales_order_lines"."tax_minor" IS 'Tax charged on this line in minor units, refunded proportionally to the units returned.';
COMMENT ON COLUMN "sales_order_lines"."discount_minor" IS 'Discount applied to this line. Refunding the list price of a discounted item is the most common way money leaks out of a returns process.';
COMMENT ON COLUMN "sales_order_lines"."is_final_sale" IS 'True for clearance and personalised goods that cannot be returned. Stored per line because the policy at purchase time is what binds, not the policy today.';

CREATE INDEX "idx_order_lines_order"
ON "sales_order_lines" ("sales_order_id");
CREATE INDEX "idx_order_lines_sku"
ON "sales_order_lines" ("sku");

CREATE TABLE IF NOT EXISTS "return_policies" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Policy name shown in the admin, e.g. Standard 30 day or Electronics 14 day.
	"name" VARCHAR(120) NOT NULL,
	-- global | category | sku | channel. The most specific matching policy wins, which is what lets one category be tightened without rewriting the rest.
	"scope_type" VARCHAR(16) NOT NULL DEFAULT 'global',
	-- Category name, SKU or channel the policy applies to. Null when scope_type is global.
	"scope_value" VARCHAR(120),
	-- Days from delivery in which a return may be started. Counted from delivered_at, not from the order date.
	"window_days" INTEGER NOT NULL DEFAULT 30,
	-- Percentage of the line value withheld on an accepted return. Stored as a percentage and applied to the snapshotted price, so the fee is reproducible years later.
	"restocking_fee_pct" NUMERIC(5,2) NOT NULL DEFAULT 0,
	-- True where the item is unsellable without its box. Drives a grading rule at inspection rather than an automatic rejection.
	"requires_original_packaging" BOOLEAN NOT NULL DEFAULT false,
	-- Whether the merchant pays the return shipping by default. Reason still overrides it: a defective item is always the merchant cost.
	"free_return" BOOLEAN NOT NULL DEFAULT true,
	-- First day this policy version applies. Policies are versioned by date because a return must be judged under the policy in force when the order was placed.
	"effective_from" DATE NOT NULL,
	-- Last day it applies. Null while current.
	"effective_to" DATE,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "return_policies" IS 'Eligibility rules, versioned in time. Changing a window is not an edit to this row but a new row, because the customer is owed the terms that were on the page when they bought.';
COMMENT ON COLUMN "return_policies"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "return_policies"."name" IS 'Policy name shown in the admin, e.g. Standard 30 day or Electronics 14 day.';
COMMENT ON COLUMN "return_policies"."scope_type" IS 'global | category | sku | channel. The most specific matching policy wins, which is what lets one category be tightened without rewriting the rest.';
COMMENT ON COLUMN "return_policies"."scope_value" IS 'Category name, SKU or channel the policy applies to. Null when scope_type is global.';
COMMENT ON COLUMN "return_policies"."window_days" IS 'Days from delivery in which a return may be started. Counted from delivered_at, not from the order date.';
COMMENT ON COLUMN "return_policies"."restocking_fee_pct" IS 'Percentage of the line value withheld on an accepted return. Stored as a percentage and applied to the snapshotted price, so the fee is reproducible years later.';
COMMENT ON COLUMN "return_policies"."requires_original_packaging" IS 'True where the item is unsellable without its box. Drives a grading rule at inspection rather than an automatic rejection.';
COMMENT ON COLUMN "return_policies"."free_return" IS 'Whether the merchant pays the return shipping by default. Reason still overrides it: a defective item is always the merchant cost.';
COMMENT ON COLUMN "return_policies"."effective_from" IS 'First day this policy version applies. Policies are versioned by date because a return must be judged under the policy in force when the order was placed.';
COMMENT ON COLUMN "return_policies"."effective_to" IS 'Last day it applies. Null while current.';

CREATE INDEX "idx_policies_scope_effective"
ON "return_policies" ("scope_type", "scope_value", "effective_from");

CREATE TABLE IF NOT EXISTS "return_reasons" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Stable machine code used by the storefront and by analytics, e.g. too_small or arrived_damaged.
	"code" VARCHAR(32) NOT NULL UNIQUE,
	-- Text the customer picks from. Wording changes; the code does not.
	"label" VARCHAR(160) NOT NULL,
	-- remorse | fit | defective | wrong_item | damaged_in_transit | not_as_described | late_delivery. The category, not the label, drives every downstream rule.
	"reason_category" VARCHAR(24) NOT NULL,
	-- True when the merchant caused it. Decides who pays return shipping and whether a restocking fee may be charged at all.
	"is_merchant_fault" BOOLEAN NOT NULL DEFAULT false,
	-- Whether the RMA is granted without human review. Defective claims on high-value goods usually are not.
	"auto_approve" BOOLEAN NOT NULL DEFAULT true,
	-- Whether the customer must upload evidence. Cheap fraud deterrent for damage claims, and the photo is what a carrier claim needs anyway.
	"requires_photo" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "return_reasons" IS 'The controlled vocabulary of why. A free-text reason box tells you nothing in aggregate; a category tells you whether the problem is your sizing chart, your packaging or your courier.';
COMMENT ON COLUMN "return_reasons"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "return_reasons"."code" IS 'Stable machine code used by the storefront and by analytics, e.g. too_small or arrived_damaged.';
COMMENT ON COLUMN "return_reasons"."label" IS 'Text the customer picks from. Wording changes; the code does not.';
COMMENT ON COLUMN "return_reasons"."reason_category" IS 'remorse | fit | defective | wrong_item | damaged_in_transit | not_as_described | late_delivery. The category, not the label, drives every downstream rule.';
COMMENT ON COLUMN "return_reasons"."is_merchant_fault" IS 'True when the merchant caused it. Decides who pays return shipping and whether a restocking fee may be charged at all.';
COMMENT ON COLUMN "return_reasons"."auto_approve" IS 'Whether the RMA is granted without human review. Defective claims on high-value goods usually are not.';
COMMENT ON COLUMN "return_reasons"."requires_photo" IS 'Whether the customer must upload evidence. Cheap fraud deterrent for damage claims, and the photo is what a carrier claim needs anyway.';

CREATE TABLE IF NOT EXISTS "return_authorisations" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Reference the customer writes on the parcel and quotes in email.
	"rma_number" VARCHAR(32) NOT NULL UNIQUE,
	-- Requester. Denormalised from the order so a risk lookup does not need a join through it.
	"customer_id" BIGINT NOT NULL,
	-- Order being returned against.
	"sales_order_id" BIGINT NOT NULL,
	-- Policy version applied when eligibility was judged. Null only for a goodwill exception, which is itself worth being able to count.
	"policy_id" BIGINT,
	-- requested | approved | rejected | label_issued | in_transit | received | inspected | settled | expired | cancelled. Expired is the common ending: most approved returns are never sent back.
	"status" VARCHAR(24) NOT NULL DEFAULT 'requested',
	-- When the customer started the request. The moment eligibility is evaluated, so a request made inside the window stays valid while it is reviewed.
	"requested_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When authorisation was granted. Null while pending or rejected.
	"approved_at" TIMESTAMPTZ,
	-- Deadline for the parcel to be handed to the carrier. Without it, warehouses receive parcels against six-month-old authorisations nobody has reserved stock or money for.
	"expires_at" TIMESTAMPTZ,
	-- refund | exchange | store_credit | repair. What the customer asked for, which is not necessarily what inspection concludes they get.
	"resolution_preference" VARCHAR(16) NOT NULL DEFAULT 'refund',
	-- Risk score snapshotted at request time, so a later decision can be explained with the information that was actually available.
	"risk_score_at_request" NUMERIC(5,2),
	-- Agent notes on a manual decision. The audit trail for an exception granted outside policy.
	"review_notes" TEXT,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "return_authorisations" IS 'The authorisation, not the refund. It is a promise to accept goods back under stated conditions, and it can expire unused — which is why it cannot be modelled as a reversal of the order.';
COMMENT ON COLUMN "return_authorisations"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "return_authorisations"."rma_number" IS 'Reference the customer writes on the parcel and quotes in email.';
COMMENT ON COLUMN "return_authorisations"."customer_id" IS 'Requester. Denormalised from the order so a risk lookup does not need a join through it.';
COMMENT ON COLUMN "return_authorisations"."sales_order_id" IS 'Order being returned against.';
COMMENT ON COLUMN "return_authorisations"."policy_id" IS 'Policy version applied when eligibility was judged. Null only for a goodwill exception, which is itself worth being able to count.';
COMMENT ON COLUMN "return_authorisations"."status" IS 'requested | approved | rejected | label_issued | in_transit | received | inspected | settled | expired | cancelled. Expired is the common ending: most approved returns are never sent back.';
COMMENT ON COLUMN "return_authorisations"."requested_at" IS 'When the customer started the request. The moment eligibility is evaluated, so a request made inside the window stays valid while it is reviewed.';
COMMENT ON COLUMN "return_authorisations"."approved_at" IS 'When authorisation was granted. Null while pending or rejected.';
COMMENT ON COLUMN "return_authorisations"."expires_at" IS 'Deadline for the parcel to be handed to the carrier. Without it, warehouses receive parcels against six-month-old authorisations nobody has reserved stock or money for.';
COMMENT ON COLUMN "return_authorisations"."resolution_preference" IS 'refund | exchange | store_credit | repair. What the customer asked for, which is not necessarily what inspection concludes they get.';
COMMENT ON COLUMN "return_authorisations"."risk_score_at_request" IS 'Risk score snapshotted at request time, so a later decision can be explained with the information that was actually available.';
COMMENT ON COLUMN "return_authorisations"."review_notes" IS 'Agent notes on a manual decision. The audit trail for an exception granted outside policy.';

CREATE INDEX "idx_rma_customer_requested"
ON "return_authorisations" ("customer_id", "requested_at");
CREATE INDEX "idx_rma_status"
ON "return_authorisations" ("status");
CREATE INDEX "idx_rma_order"
ON "return_authorisations" ("sales_order_id");

CREATE TABLE IF NOT EXISTS "return_lines" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent authorisation.
	"return_authorisation_id" BIGINT NOT NULL,
	-- Line being returned. The link that caps the returnable quantity and fixes the refundable price.
	"sales_order_line_id" BIGINT NOT NULL,
	-- Why this item is coming back. Per line, because a customer returning three items rarely has one reason.
	"reason_id" BIGINT NOT NULL,
	-- Units the customer says they are sending. Summed across all authorisations against the line, this may never exceed the quantity bought.
	"quantity_requested" INTEGER NOT NULL,
	-- Units that actually arrived. Different from requested more often than anyone expects, and the gap is a fraud signal as much as an operations one.
	"quantity_received" INTEGER NOT NULL DEFAULT 0,
	-- What the customer typed. Worthless in aggregate, occasionally decisive in a dispute.
	"customer_comment" TEXT,
	-- Value of the requested units in minor units, computed from the snapshotted line price, discount and tax. Frozen here so a settlement can never be recalculated against a changed catalogue.
	"refundable_amount_minor" BIGINT NOT NULL,
	-- Fee withheld on this line in minor units, derived from the policy but stored, because the percentage may change before the parcel arrives.
	"restocking_fee_minor" BIGINT NOT NULL DEFAULT 0,
	-- ISO 4217 currency, copied from the order so a refund cannot drift into a different one.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "return_lines" IS 'What is coming back, and what it is worth. Requested against received is the central pair: everything downstream — inspection, disposition, settlement — is scoped to the units that physically arrived.';
COMMENT ON COLUMN "return_lines"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "return_lines"."return_authorisation_id" IS 'Parent authorisation.';
COMMENT ON COLUMN "return_lines"."sales_order_line_id" IS 'Line being returned. The link that caps the returnable quantity and fixes the refundable price.';
COMMENT ON COLUMN "return_lines"."reason_id" IS 'Why this item is coming back. Per line, because a customer returning three items rarely has one reason.';
COMMENT ON COLUMN "return_lines"."quantity_requested" IS 'Units the customer says they are sending. Summed across all authorisations against the line, this may never exceed the quantity bought.';
COMMENT ON COLUMN "return_lines"."quantity_received" IS 'Units that actually arrived. Different from requested more often than anyone expects, and the gap is a fraud signal as much as an operations one.';
COMMENT ON COLUMN "return_lines"."customer_comment" IS 'What the customer typed. Worthless in aggregate, occasionally decisive in a dispute.';
COMMENT ON COLUMN "return_lines"."refundable_amount_minor" IS 'Value of the requested units in minor units, computed from the snapshotted line price, discount and tax. Frozen here so a settlement can never be recalculated against a changed catalogue.';
COMMENT ON COLUMN "return_lines"."restocking_fee_minor" IS 'Fee withheld on this line in minor units, derived from the policy but stored, because the percentage may change before the parcel arrives.';
COMMENT ON COLUMN "return_lines"."currency_code" IS 'ISO 4217 currency, copied from the order so a refund cannot drift into a different one.';

CREATE INDEX "idx_return_lines_rma"
ON "return_lines" ("return_authorisation_id");
CREATE INDEX "idx_return_lines_order_line"
ON "return_lines" ("sales_order_line_id");

CREATE TABLE IF NOT EXISTS "return_shipments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Authorisation the parcel belongs to. One RMA can produce several parcels when items ship from different places.
	"return_authorisation_id" BIGINT NOT NULL,
	-- Carrier handling the return leg, often not the one that delivered the order.
	"carrier" VARCHAR(60) NOT NULL,
	-- Tracking number. Null until a label is generated, and its first scan is what moves the RMA to in_transit.
	"tracking_number" VARCHAR(80),
	-- Object storage key for the generated label PDF. The file never belongs in the database.
	"label_storage_key" VARCHAR(400),
	-- What the label cost in minor units. Return shipping is usually the largest single cost of a return and is invisible unless it is stored.
	"label_cost_minor" BIGINT NOT NULL DEFAULT 0,
	-- ISO 4217 currency of label_cost_minor.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- merchant | customer. Derived from the reason and the policy at issue time, then frozen, because who pays is a promise made when the label was sent.
	"paid_by" VARCHAR(16) NOT NULL DEFAULT 'merchant',
	-- First carrier scan. Null while the customer still has the parcel.
	"shipped_at" TIMESTAMPTZ,
	-- Arrival at the returns facility. The clock that service-level promises about refund speed are measured against.
	"delivered_at" TIMESTAMPTZ,
	-- label_issued | in_transit | delivered | lost | unused. Unused is the resting state of most return labels ever generated.
	"status" VARCHAR(24) NOT NULL DEFAULT 'label_issued',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "return_shipments" IS 'The inbound leg. Modelled separately from the authorisation because a label has its own cost, its own lifecycle and its own failure mode — the parcel that never arrives.';
COMMENT ON COLUMN "return_shipments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "return_shipments"."return_authorisation_id" IS 'Authorisation the parcel belongs to. One RMA can produce several parcels when items ship from different places.';
COMMENT ON COLUMN "return_shipments"."carrier" IS 'Carrier handling the return leg, often not the one that delivered the order.';
COMMENT ON COLUMN "return_shipments"."tracking_number" IS 'Tracking number. Null until a label is generated, and its first scan is what moves the RMA to in_transit.';
COMMENT ON COLUMN "return_shipments"."label_storage_key" IS 'Object storage key for the generated label PDF. The file never belongs in the database.';
COMMENT ON COLUMN "return_shipments"."label_cost_minor" IS 'What the label cost in minor units. Return shipping is usually the largest single cost of a return and is invisible unless it is stored.';
COMMENT ON COLUMN "return_shipments"."currency_code" IS 'ISO 4217 currency of label_cost_minor.';
COMMENT ON COLUMN "return_shipments"."paid_by" IS 'merchant | customer. Derived from the reason and the policy at issue time, then frozen, because who pays is a promise made when the label was sent.';
COMMENT ON COLUMN "return_shipments"."shipped_at" IS 'First carrier scan. Null while the customer still has the parcel.';
COMMENT ON COLUMN "return_shipments"."delivered_at" IS 'Arrival at the returns facility. The clock that service-level promises about refund speed are measured against.';
COMMENT ON COLUMN "return_shipments"."status" IS 'label_issued | in_transit | delivered | lost | unused. Unused is the resting state of most return labels ever generated.';

CREATE INDEX "idx_return_shipments_rma"
ON "return_shipments" ("return_authorisation_id");
CREATE INDEX "idx_return_shipments_tracking"
ON "return_shipments" ("tracking_number");

CREATE TABLE IF NOT EXISTS "return_inspections" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Line being inspected.
	"return_line_id" BIGINT NOT NULL,
	-- When the goods were examined.
	"inspected_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Operator or station that graded it, so a grading pattern can be traced to a person.
	"inspected_by" VARCHAR(80),
	-- Units examined in this pass. A line can be inspected in more than one pass when a parcel is split across benches.
	"quantity_inspected" INTEGER NOT NULL,
	-- a | b | c | scrap. A is sellable as new, B needs repackaging, C is open-box or outlet, scrap has no recoverable value. The grade, not the reason the customer gave, decides the disposition.
	"grade" VARCHAR(16) NOT NULL,
	-- False when what arrived is not what was authorised — a different SKU, an empty box, a brick. This single flag is the highest-value fraud signal in the whole schema.
	"matches_declared" BOOLEAN NOT NULL DEFAULT true,
	-- What the inspector saw, in words, for disputes and for vendor claims.
	"condition_notes" TEXT,
	-- Photo references and checklist results captured at the bench. Schemaless because the checklist differs per category and nothing joins to an individual item.
	"evidence" JSONB,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "return_inspections" IS 'What actually came back, as opposed to what was claimed. Inspection is the point where a return stops being a customer story and becomes a fact, and it is why refunds are not issued at authorisation time.';
COMMENT ON COLUMN "return_inspections"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "return_inspections"."return_line_id" IS 'Line being inspected.';
COMMENT ON COLUMN "return_inspections"."inspected_at" IS 'When the goods were examined.';
COMMENT ON COLUMN "return_inspections"."inspected_by" IS 'Operator or station that graded it, so a grading pattern can be traced to a person.';
COMMENT ON COLUMN "return_inspections"."quantity_inspected" IS 'Units examined in this pass. A line can be inspected in more than one pass when a parcel is split across benches.';
COMMENT ON COLUMN "return_inspections"."grade" IS 'a | b | c | scrap. A is sellable as new, B needs repackaging, C is open-box or outlet, scrap has no recoverable value. The grade, not the reason the customer gave, decides the disposition.';
COMMENT ON COLUMN "return_inspections"."matches_declared" IS 'False when what arrived is not what was authorised — a different SKU, an empty box, a brick. This single flag is the highest-value fraud signal in the whole schema.';
COMMENT ON COLUMN "return_inspections"."condition_notes" IS 'What the inspector saw, in words, for disputes and for vendor claims.';
COMMENT ON COLUMN "return_inspections"."evidence" IS 'Photo references and checklist results captured at the bench. Schemaless because the checklist differs per category and nothing joins to an individual item.';

CREATE INDEX "idx_inspections_line_time"
ON "return_inspections" ("return_line_id", "inspected_at");
CREATE INDEX "idx_inspections_grade"
ON "return_inspections" ("grade");
CREATE INDEX "idx_inspections_mismatch"
ON "return_inspections" ("matches_declared");

CREATE TABLE IF NOT EXISTS "disposition_events" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Line whose units were disposed of.
	"return_line_id" BIGINT NOT NULL,
	-- restock | refurbish | liquidate | scrap | return_to_vendor | donate. Where the unit went after grading.
	"disposition" VARCHAR(24) NOT NULL,
	-- Units taking this path. One line splits: two restocked, one scrapped, and the split must be recorded rather than averaged.
	"quantity" INTEGER NOT NULL,
	-- When the disposition happened. Days between delivery and disposition is the metric that exposes a backed-up returns bench.
	"performed_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Where it went — a bin code, a refurbishment queue, a liquidation lot. Kept as a loose reference so this table does not need to know about warehouse internals.
	"destination_reference" VARCHAR(120),
	-- Value recovered in minor units: full cost for a restock, the liquidation price for a lot, zero for scrap. Net return cost is unknowable without it.
	"recovered_value_minor" BIGINT NOT NULL DEFAULT 0,
	-- ISO 4217 currency of recovered_value_minor.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Supplier authorisation number when the unit is sent back up the chain. The forward-logistics side of this movement lives in the warehouse inventory example.
	"vendor_rma_reference" VARCHAR(64),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "disposition_events" IS 'Append-only record of where each unit ended up. Rows are never revised: a mistaken scrap is followed by a correcting row, so recovery reporting stays reconcilable with the physical stock movement it triggered.';
COMMENT ON COLUMN "disposition_events"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "disposition_events"."return_line_id" IS 'Line whose units were disposed of.';
COMMENT ON COLUMN "disposition_events"."disposition" IS 'restock | refurbish | liquidate | scrap | return_to_vendor | donate. Where the unit went after grading.';
COMMENT ON COLUMN "disposition_events"."quantity" IS 'Units taking this path. One line splits: two restocked, one scrapped, and the split must be recorded rather than averaged.';
COMMENT ON COLUMN "disposition_events"."performed_at" IS 'When the disposition happened. Days between delivery and disposition is the metric that exposes a backed-up returns bench.';
COMMENT ON COLUMN "disposition_events"."destination_reference" IS 'Where it went — a bin code, a refurbishment queue, a liquidation lot. Kept as a loose reference so this table does not need to know about warehouse internals.';
COMMENT ON COLUMN "disposition_events"."recovered_value_minor" IS 'Value recovered in minor units: full cost for a restock, the liquidation price for a lot, zero for scrap. Net return cost is unknowable without it.';
COMMENT ON COLUMN "disposition_events"."currency_code" IS 'ISO 4217 currency of recovered_value_minor.';
COMMENT ON COLUMN "disposition_events"."vendor_rma_reference" IS 'Supplier authorisation number when the unit is sent back up the chain. The forward-logistics side of this movement lives in the warehouse inventory example.';

CREATE INDEX "idx_dispositions_line"
ON "disposition_events" ("return_line_id");
CREATE INDEX "idx_dispositions_type_time"
ON "disposition_events" ("disposition", "performed_at");

CREATE TABLE IF NOT EXISTS "return_settlements" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Authorisation being settled. Several settlements per RMA is normal: a partial refund now, the rest after a vendor credit.
	"return_authorisation_id" BIGINT NOT NULL,
	-- refund | exchange | store_credit | repair | denied. Denied is a settlement too — it closes the RMA and must be reportable.
	"settlement_type" VARCHAR(16) NOT NULL,
	-- Amount settled in minor units, net of restocking fees and any return shipping charged to the customer.
	"amount_minor" BIGINT NOT NULL DEFAULT 0,
	-- ISO 4217 currency, always the currency the order was paid in.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- original_payment | store_credit | bank_transfer | gift_card. Refunding to the original payment method is what keeps a refund from becoming a money-transmission problem.
	"refund_method" VARCHAR(24),
	-- Gateway or ledger reference for the movement. Unique, so a retried settlement job cannot pay the same customer twice.
	"payment_reference" VARCHAR(120) UNIQUE,
	-- Order number of the replacement shipped out. Populated for exchanges, and the reason an exchange is not a refund plus a new order in reporting.
	"exchange_order_number" VARCHAR(32),
	-- Credit note or gift card code issued. Kept here so unredeemed credit remains a liability that can be counted.
	"store_credit_code" VARCHAR(64),
	-- pending | processing | completed | failed. Failed refunds are common — expired cards, closed accounts — and need to be visible, not retried into silence.
	"status" VARCHAR(24) NOT NULL DEFAULT 'pending',
	-- When the money or credit actually moved, as distinct from when it was decided.
	"issued_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "return_settlements" IS 'How the customer was made whole. One RMA can settle in several ways and in several instalments, which is exactly why this is not a set of columns on the authorisation.';
COMMENT ON COLUMN "return_settlements"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "return_settlements"."return_authorisation_id" IS 'Authorisation being settled. Several settlements per RMA is normal: a partial refund now, the rest after a vendor credit.';
COMMENT ON COLUMN "return_settlements"."settlement_type" IS 'refund | exchange | store_credit | repair | denied. Denied is a settlement too — it closes the RMA and must be reportable.';
COMMENT ON COLUMN "return_settlements"."amount_minor" IS 'Amount settled in minor units, net of restocking fees and any return shipping charged to the customer.';
COMMENT ON COLUMN "return_settlements"."currency_code" IS 'ISO 4217 currency, always the currency the order was paid in.';
COMMENT ON COLUMN "return_settlements"."refund_method" IS 'original_payment | store_credit | bank_transfer | gift_card. Refunding to the original payment method is what keeps a refund from becoming a money-transmission problem.';
COMMENT ON COLUMN "return_settlements"."payment_reference" IS 'Gateway or ledger reference for the movement. Unique, so a retried settlement job cannot pay the same customer twice.';
COMMENT ON COLUMN "return_settlements"."exchange_order_number" IS 'Order number of the replacement shipped out. Populated for exchanges, and the reason an exchange is not a refund plus a new order in reporting.';
COMMENT ON COLUMN "return_settlements"."store_credit_code" IS 'Credit note or gift card code issued. Kept here so unredeemed credit remains a liability that can be counted.';
COMMENT ON COLUMN "return_settlements"."status" IS 'pending | processing | completed | failed. Failed refunds are common — expired cards, closed accounts — and need to be visible, not retried into silence.';
COMMENT ON COLUMN "return_settlements"."issued_at" IS 'When the money or credit actually moved, as distinct from when it was decided.';

CREATE INDEX "idx_settlements_rma"
ON "return_settlements" ("return_authorisation_id");
CREATE INDEX "idx_settlements_status"
ON "return_settlements" ("status");

CREATE TABLE IF NOT EXISTS "customer_return_risk" (
	-- Customer the profile describes. The primary key is the foreign key: one row per customer, rewritten in place.
	"customer_id" BIGINT,
	-- Orders in the rolling window, the denominator of the return rate.
	"orders_count" INTEGER NOT NULL DEFAULT 0,
	-- Returns in the same window, the numerator.
	"returns_count" INTEGER NOT NULL DEFAULT 0,
	-- Returns divided by orders as a percentage. Meaningless below a handful of orders, which is why the counts are stored beside it.
	"return_rate" NUMERIC(5,2) NOT NULL DEFAULT 0,
	-- Returns above a value threshold. Abuse concentrates in expensive items, so a flat rate hides the pattern.
	"high_value_return_count" INTEGER NOT NULL DEFAULT 0,
	-- Times an inspection found the wrong item or an empty box. The strongest single signal available, and it comes from the bench, not from the customer.
	"mismatch_count" INTEGER NOT NULL DEFAULT 0,
	-- Returns graded below A after a claim of unused condition. The wardrobing pattern: buy, use once, return.
	"worn_return_count" INTEGER NOT NULL DEFAULT 0,
	-- trusted | normal | elevated | blocked. Bands rather than a raw score, because staff act on a band and a score invites arguing over decimals.
	"risk_band" VARCHAR(16) NOT NULL DEFAULT 'normal',
	-- Forces every new RMA from this customer through a human, without blocking them outright.
	"manual_review_required" BOOLEAN NOT NULL DEFAULT false,
	-- When the profile was last recomputed. A stale profile used for a live decision is worse than none, so decisions snapshot the score they used.
	"computed_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("customer_id")
);

COMMENT ON TABLE "customer_return_risk" IS 'A derived profile, recomputed from orders, returns and inspections on a schedule. It is a cache with a timestamp, never a hand-edited record, which is what keeps a refund decision explainable after the fact.';
COMMENT ON COLUMN "customer_return_risk"."customer_id" IS 'Customer the profile describes. The primary key is the foreign key: one row per customer, rewritten in place.';
COMMENT ON COLUMN "customer_return_risk"."orders_count" IS 'Orders in the rolling window, the denominator of the return rate.';
COMMENT ON COLUMN "customer_return_risk"."returns_count" IS 'Returns in the same window, the numerator.';
COMMENT ON COLUMN "customer_return_risk"."return_rate" IS 'Returns divided by orders as a percentage. Meaningless below a handful of orders, which is why the counts are stored beside it.';
COMMENT ON COLUMN "customer_return_risk"."high_value_return_count" IS 'Returns above a value threshold. Abuse concentrates in expensive items, so a flat rate hides the pattern.';
COMMENT ON COLUMN "customer_return_risk"."mismatch_count" IS 'Times an inspection found the wrong item or an empty box. The strongest single signal available, and it comes from the bench, not from the customer.';
COMMENT ON COLUMN "customer_return_risk"."worn_return_count" IS 'Returns graded below A after a claim of unused condition. The wardrobing pattern: buy, use once, return.';
COMMENT ON COLUMN "customer_return_risk"."risk_band" IS 'trusted | normal | elevated | blocked. Bands rather than a raw score, because staff act on a band and a score invites arguing over decimals.';
COMMENT ON COLUMN "customer_return_risk"."manual_review_required" IS 'Forces every new RMA from this customer through a human, without blocking them outright.';
COMMENT ON COLUMN "customer_return_risk"."computed_at" IS 'When the profile was last recomputed. A stale profile used for a live decision is worse than none, so decisions snapshot the score they used.';

CREATE INDEX "idx_risk_band"
ON "customer_return_risk" ("risk_band");

